codeExamples.code:
function sayHello() {
  console.log("Hello, world!");
  console.log("Welcome to JavaScript!");
}

sayHello();  // Call the function
sayHello();  // Call it again — same output

function greetUser() {
  console.log("Hi there!");
}

function calculateArea() {
  let width = 5;
  let height = 3;
  let area = width * height;
  console.log("Area:", area);  // Area: 15
}

greetUser();      // Hi there!
calculateArea(); // Area: 15

// Function DECLARATION — hoisted
greet();  // Works! Output: "Hello!"

function greet() {
  console.log("Hello!");
}

// Function EXPRESSION — not hoisted
farewell();  // Error: Cannot access 'farewell' before initialization

const farewell = function() {
  console.log("Goodbye!");
};

// Use DECLARATIONS for reusable, named functions
function double(number) {
  return number * 2;
}

// Use EXPRESSIONS for short, one-time callbacks
const numbers = [1, 2, 3];
const doubled = numbers.map(function(n) {
  return n * 2;
});

console.log(doubled);  // [2, 4, 6]

function greet(name, timeOfDay) {
  console.log("Good " + timeOfDay + ", " + name + "!");
}

greet("Alex", "morning");   // "Good morning, Alex!"
greet("Vishnu", "evening"); // "Good evening, Vishnu!"

greet("Sam");  // "Good undefined, Sam!"
// Missing argument results in 'undefined'

function greet(name = "Guest", timeOfDay = "morning") {
  console.log("Good " + timeOfDay + ", " + name + "!");
}

greet("Alex", "evening");  // "Good evening, Alex!"
greet("Sam");              // "Good morning, Sam!"
greet();                   // "Good morning, Guest!"

greet(undefined, "night"); // "Good night, Guest!"
// undefined triggers the default

function sum(...numbers) {
  let total = 0;
  for (let num of numbers) {
    total += num;
  }
  return total;
}

console.log(sum(1, 2));       // 3
console.log(sum(1, 2, 3, 4)); // 10
console.log(sum(5));          // 5
console.log(sum());           // 0

function logWithPrefix(prefix, ...messages) {
  for (let msg of messages) {
    console.log(prefix + ": " + msg);
  }
}

logWithPrefix("INFO", "Server started", "Listening on port 3000");
// INFO: Server started
// INFO: Listening on port 3000

logWithPrefix("ERROR", "File not found");
// ERROR: File not found

function add(a, b) {
  return a + b;
}

let result = add(3, 7);
console.log(result);  // 10

// You can use the return value directly
console.log(add(5, 5));  // 10

// Return stops the function early
function checkAge(age) {
  if (age < 0) {
    return "Invalid age";  // Exits here if negative
  }
  return age >= 18 ? "Adult" : "Minor";
}

console.log(checkAge(-1));   // "Invalid age"
console.log(checkAge(20));   // "Adult"
console.log(checkAge(15));   // "Minor"

function sayHello() {
  console.log("Hello!");
  // No return statement
}

let value = sayHello();
console.log(value);  // undefined

function multiply(a, b) {
  let product = a * b;
  // Forgot the return statement!
}

console.log(multiply(3, 4));  // undefined (not 12!)
